{
  "tasks": [
    {
      "type": "cloze",
      "claim_id": "log-interpretation-workflow.c2",
      "question": "Заполните пропуск в правиле первичной разведки для терригенных пород.",
      "text": "Для терригенных пород ключевым методом первичной разведки является кривая {{1}} из-за контраста между коллектором и глинами.",
      "answers": [
        ["сопротивления", "сопротивление"]
      ],
      "explanation": "Сопротивление является ключевым методом для терригенных пород благодаря контрасту между коллектором и окружающими глинами."
    },
    {
      "type": "order",
      "claim_id": "log-interpretation-workflow.c1",
      "question": "Расставьте этапы обзорного анализа каротажных диаграмм в правильном порядке.",
      "items": [
        "Поиск чистых зон и разделение потока на терригенные породы и карбонаты",
        "Первичная оценка по ключевым кривым (сопротивление или пористость)",
        "Учет возможных осложнений (радиоактивные зоны или глинистые интервалы с низким сопротивлением)",
        "Переход к детальному анализу интервалов интереса"
      ],
      "explanation": "Алгоритм начинается с разделения пород, затем идет проверка по ключевым кривым с учетом ложных признаков и завершается детальным анализом."
    },
    {
      "type": "multi",
      "claim_id": "log-interpretation-workflow.c6",
      "question": "Какие потенциальные ловушки или особенности могут встретиться при первичном сканировании каротажа? Выберите все верные варианты.",
      "options": [
        "Некоторые зоны, похожие на глины, на самом деле могут оказаться радиоактивными продуктивными пластами",
        "Глинистые интервалы никогда не могут содержать нефть или газ",
        "Глинистые зоны могут давать нефть или газ даже при низком сопротивлении",
        "Сопротивление в карбонатах всегда остается абсолютно постоянным"
      ],
      "answer": [
        0,
        2
      ],
      "explanation": "Текст предупреждает о радиоактивных продуктивных зонах, выглядящих как глины, и о возможности притока углеводородов из глинистых интервалов с низким сопротивлением."
    }
  ],
  "card": {
    "front": "С каких шагов начинается обзор каротажных диаграмм и в чем главное отличие подходов для терригенных пород и карбонатов?",
    "back": "Обзор начинается с поиска чистых зон. Для терригенных пород базовым методом является кривая сопротивления (из-за контраста с глинами), а для карбонатов — кривая пористости (из-за изменчивости литологии и дефицита опорных глин)."
  }
}
